-- Importa os 2.073 lançamentos da planilha para a conta evandro0309@gmail.com
-- Como usar: Supabase Dashboard > SQL Editor > New query > cole tudo > Run
-- Seguro para rodar mais de uma vez: só insere se ainda não houver lançamentos.
do $$
begin
  if exists (select 1 from financeiro.lancamentos where user_id = '7544d66c-ed9b-496d-8bfa-9819590a4b5a') then
    raise notice 'Já existem lançamentos para este usuário; nada foi inserido.';
    return;
  end if;
  raise notice 'Importados % lançamentos.', (select count(*) from financeiro.lancamentos where user_id = '7544d66c-ed9b-496d-8bfa-9819590a4b5a');
end $$;
